Use a Set to track seen characters.

code:
function removeDuplicates(str) {
  const seen = new Set();
  const result = [];
  for (const char of str) {
    if (!seen.has(char)) {
      seen.add(char);
      result.push(char);
    }
  }
  return result.join('');
}
console.log(removeDuplicates('aabbcc')); // 'abc'

